from typing import List

def max_servings(n: int, q_s: List[int], a_s: List[int], b_s: List[int]) -> int:
    max_servings = 0

    for number_of_a in range(10**6):
        valid = True
        remaining_ingredients = [q_s[i] - a_s[i] * number_of_a for i in range(n)]

        for i in range(n):
            if remaining_ingredients[i] < 0:
                valid = False
                break

        if not valid:
            break

        min_number_of_b = float('inf')
        for i in range(n):
            if b_s[i] > 0:
                min_number_of_b = min(min_number_of_b, remaining_ingredients[i] // b_s[i])

        if min_number_of_b < 0:
            continue

        max_servings = max(max_servings, number_of_a + min_number_of_b)

    return max_servings
